const { db } = require('./src/db');
const { getLog, resetLog } = require('./src/audit');
const ops = {
  deleteUser:   [require('./src/ops/deleteUser').deleteUser,     'users',  'delete'],
  refundOrder:  [require('./src/ops/refundOrder').refundOrder,   'orders', 'refund'],
  banAccount:   [require('./src/ops/banAccount').banAccount,     'users',  'ban'],
  resetPassword:[require('./src/ops/resetPassword').resetPassword,'users', 'resetPassword'],
  revokeToken:  [require('./src/ops/revokeToken').revokeToken,   'tokens', 'revoke'],
  deleteFile:   [require('./src/ops/deleteFile').deleteFile,     'files',  'delete'],
};
let ok = true;
for (const [name, [fn, table, method]] of Object.entries(ops)) {
  // happy path: exactly one entry with actor/action/target
  resetLog();
  fn('actor1', 'target1');
  const log = getLog();
  const good = log.length === 1 && log[0].actor === 'actor1' && log[0].action === name && log[0].target === 'target1';
  if (!good) { ok = false; console.log('FAIL happy:', name, JSON.stringify(log)); }

  // failure path: mutation throws -> NO audit entry
  resetLog();
  const orig = db[table][method];
  db[table][method] = () => { throw new Error('boom'); };
  let threw = false;
  try { fn('actor1', 'target1'); } catch { threw = true; }
  db[table][method] = orig;
  const failLog = getLog();
  if (!threw || failLog.length !== 0) { ok = false; console.log('FAIL failure-path:', name, 'threw=', threw, JSON.stringify(failLog)); }
}
console.log(ok ? 'ALL 6 OPS: happy-path logs once, failed mutation logs nothing' : 'CONVENTION VIOLATIONS FOUND');
"
